(*第零组气缸*)
IF RTriggerCyl01.Q THEN
  nCyl0DownState := 1;
  g_boLoadCyl0DownDone := FALSE;
  g_bLoadCyl0DownOpenM := FALSE;
  g_bLoadMaterial1DelayFlag := TRUE;
  g_bLoadCylinder1UpDone := FALSE;
  g_bLoadCylinder1DownDone := FALSE;
END_IF;

IF RTriggerCyl02.Q THEN
  g_boLoadCyl0DownDone := FALSE;
  g_bLoadCyl0DownCloseM := FALSE;
  nCyl0DownState := 0;
  g_bLoadMaterial1DelayFlag := TRUE;
END_IF;

CASE nCyl0DownState OF
  0:
    nCyl0DownState := 0;
  1:
    IF LREAL_TO_INT(g_fLoadCyl0MoveTypeM) = 0 THEN
      nCyl0DownState := 2;
    ELSIF LREAL_TO_INT(g_fLoadCyl0MoveTypeM) = 1 THEN
      nCyl0DownState := 3;
    END_IF;
  2:
    IF g_dLoadCylinder1WaitBoardInputSignalM = 0.0 THEN
      nCyl0DownState := 10;
    ELSE
      M.ENABLE[183] := 0;
      nCyl0DownState := 15;
    END_IF;
  10:
    IF g_dLoadCylinder1WaitSignalM = 0.0 OR g_dLoadCylinder1WaitSignalM = 1.0 THEN
         nCyl0DownState := 20;
      ELSIF g_dLoadCylinder1WaitSignalM = 2.0 THEN
        M.ENABLE[183] := 0;
        IF NOT g_bLoadMaterialStateHmi2 THEN
          nCyl0DownState := 20;
        END_IF;
      ELSIF g_dLoadCylinder1WaitSignalM = 3.0 THEN
        M.ENABLE[183] := 0;
        IF NOT g_bLoadMaterialStateHmi3 THEN
          nCyl0DownState := 20;
        END_IF;
      ELSIF g_dLoadCylinder1WaitSignalM = 4.0 THEN
        M.ENABLE[183] := 0;
        IF NOT g_bLoadMaterialStateHmi4 THEN
          nCyl0DownState := 20;
        END_IF;
      ELSIF g_dLoadCylinder1WaitSignalM = 5.0 THEN
        M.ENABLE[183] := 0;
        IF NOT g_bLoadMaterialStateHmi5 THEN
          nCyl0DownState := 20;
        END_IF;
      ELSIF g_dLoadCylinder1WaitSignalM = 6.0 THEN
        M.ENABLE[183] := 0;
        IF NOT g_bLoadMaterialStateHmi6 THEN
          nCyl0DownState := 20;
        END_IF;
      ELSIF g_dLoadCylinder1WaitSignalM = 7.0 THEN
        M.ENABLE[183] := 0;
        IF NOT g_bLoadMaterialStateHmi7 THEN
          nCyl0DownState := 20;
        END_IF;
      ELSIF g_dLoadCylinder1WaitSignalM = 8.0 THEN
        M.ENABLE[183] := 0;
        IF NOT g_bLoadMaterialStateHmi8 THEN
          nCyl0DownState := 20;
        END_IF;
      ELSIF g_dLoadCylinder1WaitSignalM = 9.0 THEN
        M.ENABLE[183] := 0;
        IF NOT g_bLoadMaterialStateHmi9 THEN
          nCyl0DownState := 20;
        END_IF;
      ELSIF g_dLoadCylinder1WaitSignalM = 10.0 THEN
        M.ENABLE[183] := 0;
        IF NOT g_bLoadMaterialStateHmi10 THEN
          nCyl0DownState := 20;
        END_IF;
      ELSIF g_dLoadCylinder1WaitSignalM = 11.0 THEN
        M.ENABLE[183] := 0;
        IF NOT g_bLoadMaterialStateHmi11 THEN
          nCyl0DownState := 20;
        END_IF;
      END_IF; 
  15:
    nLoadCyl1DownIndex :=LREAL_TO_INT(g_dLoadCylinder1WaitSignalM) - 1;
    IF g_dLoadCylinder1WaitBoardInputSignalM = 1.0 THEN
      IF BoardInPutArray.BoolArr[nLoadCyl1DownIndex] THEN
        nCyl0DownState := 20;
      END_IF;
    ELSIF g_dLoadCylinder1WaitBoardInputSignalM = 2.0 THEN
      IF BoardInPutArray.BoolArr[nLoadCyl1DownIndex + 24] THEN
        nCyl0DownState := 20;
      END_IF;
    ELSIF g_dLoadCylinder1WaitBoardInputSignalM = 3.0 THEN
      IF BoardInPutArray.BoolArr[nLoadCyl1DownIndex + 48] THEN
        nCyl0DownState := 20;
      END_IF;
    END_IF;
  20:
    g_boLoadCyl01Up := FALSE;
    g_boLoadCyl01Down := TRUE;
    nCyl0DownState_Bak :=20;
    IF g_bLoadMaterialDownInPlaceSignal1 THEN
      IF g_bLoadCylinder1DownSignalInplaceTimeoutAlarm THEN
        nCyl0DownState := 45;
      END_IF;
      IF g_bLoadCyl01DownInPlace AND g_bLoadCyl02DownInPlace AND g_bLoadCyl03DownInPlace AND g_bLoadCyl04DownInPlace THEN
        g_boLoadCyl0DownDone := TRUE;
        nCyl0DownState := 0;
        IF NOT g_bLoadCylinderOneKeyFlag THEN
          M.ENABLE[183] := 0;
          g_bExecuteFinishedM183 := FALSE;
          g_bFinishedM183_0 := FALSE;
        END_IF;
        g_bLoadCylinder1UpDone := FALSE;
        g_bLoadCylinder1DownDone := TRUE;
        g_bLoadMaterialStateHmi1:= FALSE;
      END_IF;
    ELSE
      InPlaceDelay0(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_nLoadMaterialDownInPlaceDelay1)));
      IF InPlaceDelay0.Q THEN
        InPlaceDelay0(IN :=FALSE);
        g_boLoadCyl0DownDone := TRUE;
        nCyl0DownState := 0;
        IF NOT g_bLoadCylinderOneKeyFlag THEN
          M.ENABLE[183] := 0;
          g_bExecuteFinishedM183 := FALSE;
          g_bFinishedM183_0 := FALSE;
        END_IF;
        g_bLoadCylinder1UpDone := FALSE;
        g_bLoadCylinder1DownDone := TRUE;
        g_bLoadMaterialStateHmi1:= FALSE;
      END_IF;
    END_IF;
  3:
    IF g_dLoadCylinder1WaitBoardInputSignalM = 0.0 THEN
      nCyl0DownState := 30;
    ELSE
      M.ENABLE[183] := 0;
      nCyl0DownState := 40;
    END_IF; 
  30:
     IF g_dLoadCylinder1WaitSignalM = 0.0 OR g_dLoadCylinder1WaitSignalM = 1.0 THEN
         nCyl0DownState := 35;
      ELSIF g_dLoadCylinder1WaitSignalM = 2.0 THEN
        M.ENABLE[183] := 0;
        IF g_bLoadMaterialStateHmi2 THEN
          nCyl0DownState := 35;
        END_IF;
      ELSIF g_dLoadCylinder1WaitSignalM = 3.0 THEN
        M.ENABLE[183] := 0;
        IF g_bLoadMaterialStateHmi3 THEN
          nCyl0DownState := 35;
        END_IF;
      ELSIF g_dLoadCylinder1WaitSignalM = 4.0 THEN
        M.ENABLE[183] := 0;
        IF g_bLoadMaterialStateHmi4 THEN
          nCyl0DownState := 35;
        END_IF;
      ELSIF g_dLoadCylinder1WaitSignalM = 5.0 THEN
        M.ENABLE[183] := 0;
        IF g_bLoadMaterialStateHmi5 THEN
          nCyl0DownState := 35;
        END_IF;
      ELSIF g_dLoadCylinder1WaitSignalM = 6.0 THEN
        M.ENABLE[183] := 0;
        IF g_bLoadMaterialStateHmi6 THEN
          nCyl0DownState := 35;
        END_IF;
      ELSIF g_dLoadCylinder1WaitSignalM = 7.0 THEN
        M.ENABLE[183] := 0;
        IF g_bLoadMaterialStateHmi7 THEN
          nCyl0DownState := 35;
        END_IF;
      ELSIF g_dLoadCylinder1WaitSignalM = 8.0 THEN
        M.ENABLE[183] := 0;
        IF g_bLoadMaterialStateHmi8 THEN
          nCyl0DownState := 35;
        END_IF;
      ELSIF g_dLoadCylinder1WaitSignalM = 9.0 THEN
        M.ENABLE[183] := 0;
        IF g_bLoadMaterialStateHmi9 THEN
          nCyl0DownState := 35;
        END_IF;
      ELSIF g_dLoadCylinder1WaitSignalM = 10.0 THEN
        M.ENABLE[183] := 0;
        IF g_bLoadMaterialStateHmi10 THEN
          nCyl0DownState := 35;
        END_IF;
      ELSIF g_dLoadCylinder1WaitSignalM = 11.0 THEN
        M.ENABLE[183] := 0;
        IF g_bLoadMaterialStateHmi11 THEN
          nCyl0DownState := 35;
        END_IF;
      END_IF; 
  35:
    g_boLoadCyl01Up := TRUE;
    g_boLoadCyl01Down := FALSE;
    nCyl0DownState_Bak :=35;
    IF g_bLoadMaterialUpInPlaceSignal1 THEN
      IF g_bLoadCylinder1UpSignalInplaceTimeoutAlarm THEN
        nCyl0DownState := 45;
      END_IF;
      IF g_bLoadCyl01UpInPlace AND g_bLoadCyl02UpInPlace AND g_bLoadCyl03UpInPlace AND g_bLoadCyl04UpInPlace THEN
        g_boLoadCyl0DownDone := TRUE;
        nCyl0DownState := 0;
        IF NOT g_bLoadCylinderOneKeyFlag THEN
          M.ENABLE[183] := 0;
          g_bExecuteFinishedM183 := FALSE;
          g_bFinishedM183_0 := FALSE;
        END_IF;
        g_bLoadCylinder1UpDone := TRUE;
        g_bLoadCylinder1DownDone := FALSE;
        g_bLoadMaterialStateHmi1:= TRUE;
      END_IF;
    ELSE
      InPlaceDelay0(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_nLoadMaterialUpInPlaceDelay1)));
      IF InPlaceDelay0.Q THEN
        InPlaceDelay0(IN :=FALSE);
        g_boLoadCyl0DownDone := TRUE;
        nCyl0DownState := 0;
        IF NOT g_bLoadCylinderOneKeyFlag THEN
          M.ENABLE[183] := 0;
          g_bExecuteFinishedM183 := FALSE;
          g_bFinishedM183_0 := FALSE;
        END_IF;
        g_bLoadCylinder1UpDone := TRUE;
        g_bLoadCylinder1DownDone := FALSE;
        g_bLoadMaterialStateHmi1:= TRUE;
      END_IF;
    END_IF;
  40:
    nLoadCyl1UpIndex := LREAL_TO_INT(g_dLoadCylinder1WaitSignalM) - 1;
    IF g_dLoadCylinder1WaitBoardInputSignalM = 1.0 THEN
      IF BoardInPutArray.BoolArr[nLoadCyl1UpIndex] THEN
        nCyl0DownState := 35;
      END_IF;
    ELSIF g_dLoadCylinder1WaitBoardInputSignalM = 2.0 THEN
      IF BoardInPutArray.BoolArr[nLoadCyl1UpIndex + 24] THEN
        nCyl0DownState := 35;
      END_IF;
    ELSIF g_dLoadCylinder1WaitBoardInputSignalM = 3.0 THEN
      IF BoardInPutArray.BoolArr[nLoadCyl1UpIndex + 48] THEN
        nCyl0DownState := 35;
      END_IF;
    END_IF;
  45:
    IF g_bPlcStartBuffer THEN
      nCyl0DownState :=nCyl0DownState_Bak;  
    END_IF;  
END_CASE;

